    for p in[IMAGE,V]{pins.insert(p.into(),hash(p));}assert_eq!(hash(IMAGE),IH);let request="/home/ubuntu/src/zk-tools/zopro/tools/zolana/fixtures/transfer-1x2.json";pins.insert(request.into(),hash(request));
    let mut prior:BTreeSet<String>=serde_json::from_value(read("/home/ubuntu/src/zopro-perf-work/euler-factor-census/prior-proof-sha256.json")).unwrap();assert_eq!(prior.len(),12682);for(p,h)in read("/home/ubuntu/src/zopro-perf-work/euler-factor-census/proof-inventory.json").as_object().unwrap(){if p.ends_with(".proof"){assert_eq!(hash(p),h.as_str().unwrap());assert!(prior.insert(h.as_str().unwrap().into()));}}assert_eq!(prior.len(),12685);save(r.join("prior-proof-sha256.json"),&json!(prior));pins.insert(r.join("prior-proof-sha256.json").display().to_string(),hash(r.join("prior-proof-sha256.json")));save(r.join("capture-pins.json"),&json!(pins));
    let env=read("/home/ubuntu/src/zopro-perf-work/euler-factor-census/run-plan.json")["environment"].clone();save(r.join("capture-plan.json"),&json!({"version":1,"source_pins":r.join("capture-pins.json"),"environment":env,"steps":[{"kind":"command","name":"capture","argv":["taskset","-c","0-31",bin,IMAGE,request,r.join("proof"),r.join("frame.bin.local")],"timeout_seconds":180},{"kind":"command","name":"verify","argv":[V,IMAGE,IH,r.join("proof/0.proof"),r.join("proof/0.public"),PH],"timeout_seconds":120}]}));println!("Preparedoneobservedproofafter3primes,thenGnark");
